#!/usr/bin/env python3
"""
metadata_rag.py
===============
A self-contained Retrieval-Augmented Generation (RAG) system that uses
document metadata for both filtering and ranking.

Pipeline
--------
1. Indexing: documents (text + metadata) are tokenized and embedded with a
   lightweight TF-IDF vectorizer (standard library only, no network calls).
2. Filtering: a declarative metadata predicate (e.g. category == "guide",
   date >= ..., tags contains ...) narrows the candidate set.
3. Ranking: candidates are scored by cosine similarity to the user query.
4. Metadata re-ranking: a configurable metadata scorer (category/source
   boosts, priority, recency decay, tag overlap) is blended with the
   semantic score so metadata can promote or demote documents.
5. Answer generation: an extractive, grounded answer with source citations.

Run `python metadata_rag.py` for a self-testing demo.
"""

import math
import re
import time
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any, Callable, Dict, Iterable, List, Optional, Sequence, Tuple


# ---------------------------------------------------------------------------
# Documents
# ---------------------------------------------------------------------------

@dataclass
class Document:
    id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)


# ---------------------------------------------------------------------------
# Tokenization + TF-IDF embeddings (dependency-free)
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> List[str]:
    return _TOKEN_RE.findall(text.lower())


class TfidfVectorizer:
    """Bag-of-words TF-IDF vectorizer. transform() returns a sparse dict."""

    def __init__(self, min_df: int = 1):
        self.min_df = min_df
        self.vocab: Dict[str, int] = {}
        self.idf: Dict[str, float] = {}
        self._fitted = False

    def fit(self, texts: Iterable[str]) -> "TfidfVectorizer":
        df: Dict[str, int] = {}
        n_docs = 0
        for text in texts:
            n_docs += 1
            for term in set(tokenize(text)):
                df[term] = df.get(term, 0) + 1
        self.vocab = {
            term: i for i, term in enumerate(sorted(t for t, c in df.items() if c >= self.min_df))
        }
        for term, doc_freq in df.items():
            if term in self.vocab:
                self.idf[term] = math.log((1.0 + n_docs) / (1.0 + doc_freq)) + 1.0
        self._fitted = True
        return self

    def transform(self, text: str) -> Dict[str, float]:
        if not self._fitted:
            raise RuntimeError("vectorizer must be fit before transform")
        tf: Dict[str, float] = {}
        tokens = tokenize(text)
        for term in tokens:
            if term in self.vocab:
                tf[term] = tf.get(term, 0.0) + 1.0
        n = len(tokens) or 1
        return {term: (count / n) * self.idf[term] for term, count in tf.items()}


def cosine(a: Dict[str, float], b: Dict[str, float]) -> float:
    if not a or not b:
        return 0.0
    dot = sum(a[t] * b[t] for t in set(a) & set(b))
    na = math.sqrt(sum(v * v for v in a.values()))
    nb = math.sqrt(sum(v * v for v in b.values()))
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (na * nb)


# ---------------------------------------------------------------------------
# Declarative metadata filters
# ---------------------------------------------------------------------------

Predicate = Callable[[Dict[str, Any]], bool]


class F:
    """Builder for metadata filter predicates."""

    @staticmethod
    def eq(field_name: str, value: Any) -> Predicate:
        return lambda md: md.get(field_name) == value

    @staticmethod
    def neq(field_name: str, value: Any) -> Predicate:
        return lambda md: md.get(field_name) != value

    @staticmethod
    def one_of(field_name: str, values: Iterable[Any]) -> Predicate:
        allowed = set(values)
        return lambda md: md.get(field_name) in allowed

    @staticmethod
    def gt(field_name: str, value: Any) -> Predicate:
        def _p(md: Dict[str, Any]) -> bool:
            try:
                return md.get(field_name) is not None and md[field_name] > value
            except TypeError:
                return False
        return _p

    @staticmethod
    def gte(field_name: str, value: Any) -> Predicate:
        def _p(md: Dict[str, Any]) -> bool:
            try:
                return md.get(field_name) is not None and md[field_name] >= value
            except TypeError:
                return False
        return _p

    @staticmethod
    def lt(field_name: str, value: Any) -> Predicate:
        def _p(md: Dict[str, Any]) -> bool:
            try:
                return md.get(field_name) is not None and md[field_name] < value
            except TypeError:
                return False
        return _p

    @staticmethod
    def lte(field_name: str, value: Any) -> Predicate:
        def _p(md: Dict[str, Any]) -> bool:
            try:
                return md.get(field_name) is not None and md[field_name] <= value
            except TypeError:
                return False
        return _p

    @staticmethod
    def contains(field_name: str, value: Any) -> Predicate:
        """True when value is contained in a string or list metadata field."""
        return lambda md: value in md.get(field_name, "")

    @staticmethod
    def exists(field_name: str) -> Predicate:
        return lambda md: field_name in md and md[field_name] is not None

    @staticmethod
    def and_(*predicates: Predicate) -> Predicate:
        return lambda md: all(p(md) for p in predicates)

    @staticmethod
    def or_(*predicates: Predicate) -> Predicate:
        return lambda md: any(p(md) for p in predicates)

    @staticmethod
    def not_(predicate: Predicate) -> Predicate:
        return lambda md: not predicate(md)


# ---------------------------------------------------------------------------
# Vector store with metadata filtering
# ---------------------------------------------------------------------------

class MetadataVectorStore:
    def __init__(self, vectorizer: Optional[TfidfVectorizer] = None):
        self.vectorizer = vectorizer or TfidfVectorizer()
        self._docs: Dict[str, Document] = {}
        self._vectors: Dict[str, Dict[str, float]] = {}
        self._dirty = True

    def add(self, doc: Document) -> None:
        self._docs[doc.id] = doc
        self._dirty = True

    def fit(self) -> None:
        self.vectorizer.fit(d.text for d in self._docs.values())
        self._vectors = {did: self.vectorizer.transform(doc.text) for did, doc in self._docs.items()}
        self._dirty = False

    def add_and_fit(self, docs: Sequence[Document]) -> None:
        for doc in docs:
            self.add(doc)
        self.fit()

    def all_docs(self) -> List[Document]:
        return list(self._docs.values())

    def semantic_search(
        self, query: str, predicate: Optional[Predicate] = None, k: int = 5
    ) -> List[Tuple[float, Document]]:
        """Return top-k docs by cosine similarity, after applying the metadata filter."""
        if self._dirty:
            raise RuntimeError("store is dirty; call fit() before searching")
        qv = self.vectorizer.transform(query)
        scored: List[Tuple[float, Document]] = []
        for doc in self._docs.values():
            if predicate is not None and not predicate(doc.metadata):
                continue
            scored.append((cosine(qv, self._vectors[doc.id]), doc))
        scored.sort(key=lambda x: x[0], reverse=True)
        return scored[:k]


# ---------------------------------------------------------------------------
# Metadata-based re-ranking
# ---------------------------------------------------------------------------

@dataclass
class RankingConfig:
    """Weights that blend semantic relevance with metadata relevance signals."""
    semantic_weight: float = 0.7
    metadata_weight: float = 0.3
    category_boosts: Dict[str, float] = field(default_factory=dict)
    source_boosts: Dict[str, float] = field(default_factory=dict)
    priority_field: Optional[str] = None            # numeric, higher is better
    recency_field: Optional[str] = None             # ISO date or epoch seconds
    recency_half_life_days: float = 180.0
    tag_field: Optional[str] = None                 # list of tags compared with query tokens


class MetadataRanker:
    """Combines semantic score with normalized metadata components in [0, 1]."""

    def __init__(self, config: RankingConfig):
        self.config = config
        if not (0.0 <= config.semantic_weight <= 1.0 and 0.0 <= config.metadata_weight <= 1.0):
            raise ValueError("weights must be within [0, 1]")

    # -- components ------------------------------------------------------

    def _boost_component(self, doc: Document, boost_map: Dict[str, float], max_boost: float) -> float:
        if not boost_map:
            return 0.0
        boost = boost_map.get(doc.metadata.get("category") if boost_map is self.config.category_boosts
                              else doc.metadata.get("source"))
        if not boost or max_boost <= 1.0:
            return 0.0
        return (boost - 1.0) / (max_boost - 1.0)

    def _priority_component(self, doc: Document, min_p: float, max_p: float) -> float:
        p = doc.metadata.get(self.config.priority_field)
        if not isinstance(p, (int, float)) or max_p == min_p:
            return 0.0
        return (p - min_p) / (max_p - min_p)

    def _age_days(self, raw: Any) -> Optional[float]:
        if isinstance(raw, (int, float)):
            return max(0.0, (time.time() - float(raw)) / 86400.0)
        if isinstance(raw, str):
            try:
                dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                return max(0.0, (time.time() - dt.timestamp()) / 86400.0)
            except ValueError:
                return None
        return None

    def _recency_component(self, doc: Document) -> float:
        if not self.config.recency_field:
            return 0.0
        age = self._age_days(doc.metadata.get(self.config.recency_field))
        if age is None:
            return 0.0
        if age <= 0.0:
            return 1.0
        return math.exp(-age * math.log(2.0) / self.config.recency_half_life_days)

    def _tag_component(self, doc: Document, query_tokens: set) -> float:
        if not self.config.tag_field:
            return 0.0
        tags = doc.metadata.get(self.config.tag_field)
        if not tags:
            return 0.0
        if isinstance(tags, str):
            tags = [tags]
        tag_tokens = set(tokenize(" ".join(str(t) for t in tags)))
        if not query_tokens or not tag_tokens:
            return 0.0
        inter = len(query_tokens & tag_tokens)
        union = len(query_tokens | tag_tokens)
        return inter / union if union else 0.0

    # -- ranking ----------------------------------------------------------

    def rank(
        self,
        query: str,
        candidates: Sequence[Tuple[float, Document]],
        k: int = 5,
    ) -> List[Tuple[float, float, float, Document]]:
        """Return top-k (final, semantic, metadata, doc) tuples, best first."""
        if not candidates:
            return []
        q_tokens = set(tokenize(query))
        max_cat = max([1.0] + [b for b in self.config.category_boosts.values() if b > 1.0])
        max_src = max([1.0] + [b for b in self.config.source_boosts.values() if b > 1.0])
        prios = [d.metadata.get(self.config.priority_field) for _, d in candidates]
        prios = [p for p in prios if isinstance(p, (int, float))]
        min_p = min(prios) if prios else 0.0
        max_p = max(prios) if prios else 0.0

        results: List[Tuple[float, float, float, Document]] = []
        for sem_score, doc in candidates:
            meta_components: List[float] = []
            if self.config.category_boosts:
                meta_components.append(self._boost_component(doc, self.config.category_boosts, max_cat))
            if self.config.source_boosts:
                meta_components.append(self._boost_component(doc, self.config.source_boosts, max_src))
            if self.config.priority_field:
                meta_components.append(self._priority_component(doc, min_p, max_p))
            if self.config.recency_field:
                meta_components.append(self._recency_component(doc))
            if self.config.tag_field:
                meta_components.append(self._tag_component(doc, q_tokens))
            meta_score = sum(meta_components) / len(meta_components) if meta_components else 0.0
            final = (self.config.semantic_weight * sem_score
                     + self.config.metadata_weight * meta_score)
            results.append((final, sem_score, meta_score, doc))
        results.sort(key=lambda r: r[0], reverse=True)
        return results[:k]


# ---------------------------------------------------------------------------
# Grounded answer generation (extractive, with citations)
# ---------------------------------------------------------------------------

def extract_best_sentence(text: str, query_tokens: set) -> Optional[str]:
    sentences = re.split(r"(?<=[.!?])\s+", text.strip())
    best, best_score = None, -1.0
    for sentence in sentences:
        toks = set(tokenize(sentence))
        if not toks:
            continue
        score = len(toks & query_tokens) / math.sqrt(len(toks))
        if score > best_score:
            best, best_score = sentence.strip(), score
    return best


class GroundedAnswerGenerator:
    def __init__(self, top_k_for_answer: int = 2):
        self.top_k = top_k_for_answer

    def generate(
        self,
        query: str,
        ranked: Sequence[Tuple[float, float, float, Document]],
    ) -> Dict[str, Any]:
        q_tokens = set(tokenize(query))
        citations: List[str] = []
        evidence: List[str] = []
        for i, (_final, _sem, _meta, doc) in enumerate(ranked[: self.top_k], start=1):
            sentence = extract_best_sentence(doc.text, q_tokens)
            evidence.append(sentence or doc.text[:200])
            citations.append(f"[{i}] {doc.id}")
        if not evidence:
            return {"answer": "No relevant documents found.", "citations": [], "evidence": []}
        answer = "Based on the retrieved context:\n- " + "\n- ".join(evidence)
        answer += "\n\nSources: " + "; ".join(citations)
        return {"answer": answer, "citations": citations, "evidence": evidence}


# ---------------------------------------------------------------------------
# End-to-end RAG system
# ---------------------------------------------------------------------------

class RAGSystem:
    def __init__(self, config: Optional[RankingConfig] = None, k: int = 5):
        self.store = MetadataVectorStore()
        self.config = config or RankingConfig()
        self.ranker = MetadataRanker(self.config)
        self.generator = GroundedAnswerGenerator()
        self.k = k
        self._indexed = False

    def index(self, docs: Sequence[Document]) -> None:
        self.store.add_and_fit(docs)
        self._indexed = True

    def ask(
        self,
        question: str,
        metadata_filter: Optional[Predicate] = None,
        k: Optional[int] = None,
        retrieval_pool: int = 50,
    ) -> Dict[str, Any]:
        """Retrieve -> filter by metadata -> re-rank by semantic + metadata -> answer."""
        if not self._indexed:
            raise RuntimeError("index() must be called before ask()")
        top_k = k or self.k
        candidates = self.store.semantic_search(question, predicate=metadata_filter, k=retrieval_pool)
        ranked = self.ranker.rank(question, candidates, k=top_k)
        return {
            "question": question,
            "results": ranked,
            **self.generator.generate(question, ranked),
        }


