def fmt_result(entry: Tuple[float, float, float, Document]) -> str:
    final, sem, meta, doc = entry
    return (f"  {doc.id:9s} final={final:.4f} semantic={sem:.4f} metadata={meta:.4f} "
            f"| priority={doc.metadata.get('priority')} category={doc.metadata.get('category')} "
            f"tags={doc.metadata.get('tags')}")


def run_demo() -> None:
    corpus = build_corpus()

    config = RankingConfig(
        semantic_weight=0.7,
        metadata_weight=0.3,
        category_boosts={"incident": 1.8, "release": 1.3},
        source_boosts={"status": 1.2},
        priority_field="priority",
        recency_field="last_updated",
        recency_half_life_days=120.0,
        tag_field="tags",
    )
    rag = RAGSystem(config=config, k=3)
    rag.index(corpus)

    print("=" * 78)
    print("DEMO 1 - metadata filtering: category == 'guide'")
    print("=" * 78)
    q1 = "how do I authenticate with an API key?"
    res1 = rag.ask(q1, metadata_filter=F.eq("category", "guide"))
    for entry in res1["results"]:
        print(fmt_result(entry))
    assert res1["results"], "query 1 returned no results"
    assert all(r[3].metadata["category"] == "guide" for r in res1["results"]), \
        "metadata filter was not applied"
    assert res1["citations"], "answer must include citations"

    print()
    print("=" * 78)
    print("DEMO 2 - compound filter: source == 'docs' AND tags contain 'api' AND priority >= 3")
    print("=" * 78)
    compound = F.and_(
        F.eq("source", "docs"),
        F.contains("tags", "api"),
        F.gte("priority", 3),
    )
    res2 = rag.ask("what should I do about api keys and authentication", metadata_filter=compound)
    for entry in res2["results"]:
        print(fmt_result(entry))
    assert res2["results"], "query 2 returned no results"
    for _final, _sem, _meta, doc in res2["results"]:
        assert doc.metadata["source"] == "docs"
        assert "api" in doc.metadata["tags"]
        assert doc.metadata["priority"] >= 3

    print()
    print("=" * 78)
    print("DEMO 3 - no filter (category 'incident' boosted via metadata ranking)")
    print("=" * 78)
    res3 = rag.ask("database lock error on projects endpoint 1042")
    for entry in res3["results"]:
        print(fmt_result(entry))
    assert res3["results"][0][3].id == "doc-004", \
        "category/source boost should surface the incident report first"

    print()
    print("=" * 78)
    print("GENERATED ANSWER (DEMO 1)")
    print("=" * 78)
    print(res1["answer"])

    # -- targeted metadata-ranking checks ---------------------------------
    print()
    print("=" * 78)
    print("UNIT CHECK - metadata priority breaks a semantic tie")
    print("=" * 78)
    same_text = "Rotate credentials regularly and revoke stale tokens."
    d_hi = Document("t-high", same_text,
                    {"category": "guide", "priority": 5, "tags": ["security"],
                     "last_updated": "2025-07-01"})
    d_lo = Document("t-low", same_text,
                    {"category": "guide", "priority": 1, "tags": ["security"],
                     "last_updated": "2025-07-01"})
    rag2 = RAGSystem(config=RankingConfig(priority_field="priority", tag_field="tags"), k=2)
    rag2.index([d_hi, d_lo])
    res4 = rag2.ask("rotate credentials and revoke tokens")
    for entry in res4["results"]:
        print(fmt_result(entry))
    assert res4["results"][0][3].id == "t-high", "priority metadata should break the tie"

    print()
    print("=" * 78)
    print("UNIT CHECK - recency metadata breaks a semantic tie")
    print("=" * 78)
    d_new = Document("t-new", same_text,
                     {"category": "guide", "priority": 1, "tags": ["security"],
                      "last_updated": "2025-07-01"})
    d_old = Document("t-old", same_text,
                     {"category": "guide", "priority": 1, "tags": ["security"],
                      "last_updated": "2020-01-01"})
    rag3 = RAGSystem(config=RankingConfig(recency_field="last_updated",
                                          recency_half_life_days=120.0), k=2)
    rag3.index([d_new, d_old])
    res5 = rag3.ask("rotate credentials and revoke tokens")
    for entry in res5["results"]:
        print(fmt_result(entry))
    assert res5["results"][0][3].id == "t-new", "recency metadata should break the tie"

    # -- invariant checks --------------------------------------------------
    for res in (res1, res2, res3):
        for final, sem, meta, _doc in res["results"]:
            assert 0.0 <= sem <= 1.0, "semantic score out of range"
            assert 0.0 <= meta <= 1.0, "metadata score out of range"
            assert 0.0 <= final <= 1.0, "final score out of range"
        finals = [r[0] for r in res["results"]]
        assert finals == sorted(finals, reverse=True), "results not sorted best-first"

    # -- filter actually narrows the corpus --------------------------------
    all_ids = {d.id for d in rag.store.all_docs()}
    filtered_ids = {r[3].id for r in res1["results"]}
    assert filtered_ids <= all_ids and len(filtered_ids) < len(all_ids), \
        "metadata filtering did not narrow the candidate set"

    print()
    print("ALL ASSERTIONS PASSED")


if __name__ == "__main__":
    run_demo()
